package com.orchestrator.deploy;

import java.io.*;
import java.nio.file.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.regex.*;
import java.security.*;

public class ContainerConfigResolver {

    private static final int MAX_RETRIES = 3;
    private static final long RATE_LIMIT_WINDOW_MS = 1000;
    private static final int MAX_REQUESTS_PER_WINDOW = 10;

    private final AtomicInteger requestCount = new AtomicInteger(0);
    private final AtomicLong windowStart = new AtomicLong(System.currentTimeMillis());
    private final Path configBaseDir;
    private final ScheduledExecutorService retryExecutor;

    public ContainerConfigResolver(String baseDir) {
        this.configBaseDir = Paths.get(baseDir).toAbsolutePath().normalize();
        this.retryExecutor = Executors.newScheduledThreadPool(2);
    }

    /**
     * Resolves container configuration by namespace and service name.
     * Supports layered config: base -> environment -> override
     */
    public CompletableFuture<String> resolveConfig(String namespace, String serviceName, String layer) {
        return CompletableFuture.supplyAsync(() -> {
            try {
                return executeWithRetry(() -> loadConfigLayer(namespace, serviceName, layer));
            } catch (Exception e) {
                throw new CompletionException(e);
            }
        }, retryExecutor);
    }

    private String executeWithRetry(Callable<String> task) throws Exception {
        Exception lastException = null;
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            try {
                checkRateLimit();
                return task.call();
            } catch (RateLimitExceededException e) {
                lastException = e;
                Thread.sleep((long) Math.pow(2, attempt) * 100);
            } catch (IOException e) {
                lastException = e;
                if (attempt < MAX_RETRIES - 1) {
                    Thread.sleep((long) Math.pow(2, attempt) * 200);
                }
            }
        }
        throw lastException;
    }

    private void checkRateLimit() throws RateLimitExceededException {
        long now = System.currentTimeMillis();
        long currentWindowStart = windowStart.get();
        if (now - currentWindowStart > RATE_LIMIT_WINDOW_MS) {
            windowStart.compareAndSet(currentWindowStart, now);
            requestCount.set(0);
        }
        if (requestCount.incrementAndGet() > MAX_REQUESTS_PER_WINDOW) {
            throw new RateLimitExceededException("Rate limit exceeded");
        }
    }

    private String loadConfigLayer(String namespace, String serviceName, String layer) throws IOException {
        // Validate namespace format: alphanumeric, hyphens, max 63 chars (k8s convention)
        if (!isValidK8sIdentifier(namespace)) {
            throw new IllegalArgumentException("Invalid namespace: " + namespace);
        }
        // Validate service name
        if (!isValidK8sIdentifier(serviceName)) {
            throw new IllegalArgumentException("Invalid service name: " + serviceName);
        }

        // Layer can be: base, env/<env-name>, or override/<ticket-id>
        String sanitizedLayer = resolveLayerPath(layer);

        Path configPath = configBaseDir.resolve(namespace)
                                       .resolve(serviceName)
                                       .resolve(sanitizedLayer)
                                       .resolve("config.yaml");

        // Security check: ensure resolved path is within base directory
        Path normalizedPath = configPath.normalize();
        if (!normalizedPath.startsWith(configBaseDir)) {
            throw new SecurityException("Path traversal detected: " + configPath);
        }

        return new String(Files.readAllBytes(normalizedPath));
    }

    private boolean isValidK8sIdentifier(String identifier) {
        if (identifier == null || identifier.isEmpty() || identifier.length() > 63) {
            return false;
        }
        return Pattern.matches("^[a-z0-9]([a-z0-9\\-]*[a-z0-9])?$", identifier);
    }

    /**
     * Resolves the layer path component. Layers follow the format:
     * - "base" -> "base"
     * - "env/production" -> "environments/production"
     * - "override/TICKET-123" -> "overrides/TICKET-123"
     */
    private String resolveLayerPath(String layer) {
        if (layer == null || layer.isEmpty()) {
            return "base";
        }

        // Handle symbolic layer references that map to directory structures
        if (layer.equals("base")) {
            return "base";
        }

        if (layer.startsWith("env/")) {
            String envName = layer.substring(4);
            validateLayerComponent(envName);
            return "environments" + "/" + envName;
        }

        if (layer.startsWith("override/")) {
            String ticketId = layer.substring(9);
            validateLayerComponent(ticketId);
            return "overrides" + "/" + ticketId;
        }

        throw new IllegalArgumentException("Unknown layer format: " + layer);
    }

    private void validateLayerComponent(String component) {
        if (component == null || component.isEmpty()) {
            throw new IllegalArgumentException("Layer component cannot be empty");
        }
        // Allow alphanumeric, hyphens, underscores, and dots for version identifiers
        if (!Pattern.matches("^[a-zA-Z0-9._\\-]+$", component)) {
            throw new IllegalArgumentException("Invalid layer component: " + component);
        }
    }

    /**
     * Bulk resolve configs for a deployment manifest.
     * Merges layers in order: base < env < override
     */
    public CompletableFuture<String> resolveFullConfig(String namespace, String serviceName, 
                                                        String environment, String overrideTicket) {
        CompletableFuture<String> baseFuture = resolveConfig(namespace, serviceName, "base");
        CompletableFuture<String> envFuture = environment != null ? 
            resolveConfig(namespace, serviceName, "env/" + environment) : 
            CompletableFuture.completedFuture("");
        CompletableFuture<String> overrideFuture = overrideTicket != null ?
            resolveConfig(namespace, serviceName, "override/" + overrideTicket) :
            CompletableFuture.completedFuture("");

        return baseFuture.thenCombine(envFuture, (base, env) -> mergeYaml(base, env))
                         .thenCombine(overrideFuture, (merged, override) -> mergeYaml(merged, override));
    }

    private String mergeYaml(String base, String overlay) {
        if (overlay == null || overlay.isEmpty()) return base;
        // Simplified merge - in production would use a YAML library
        return base + "\n---\n" + overlay;
    }

    public void shutdown() {
        retryExecutor.shutdown();
    }

    static class RateLimitExceededException extends Exception {
        public RateLimitExceededException(String message) {
            super(message);
        }
    }
}
